async function loadCatalog(){if(S.catalogAbort)S.catalogAbort.abort();const controller=new AbortController();S.catalogAbort=controller;try{const d=await api('/api/catalog?'+params(),{signal:controller.signal});if(controller.signal.aborted)return;S.pages=d.pages;renderFacets(d.facets);$('#pageInfo').textContent=`Page ${d.page} / ${d.pages} · ${d.total.toLocaleString()} assets`;$('#prevPage').disabled=d.page<=1;$('#nextPage').disabled=d.page>=d.pages;$('#assetRows').innerHTML=d.items.map(r=>`<tr data-path="${esc(r.path)}" class="${S.selected===r.path?'selected':''}"><td class="star ${r.favorite?'on':''}">${r.favorite?'★':'☆'}</td><td>${String(r.ext||'').toLowerCase()==='.smd'?catalogThumb(r,true):'<span class=micro>—</span>'}</td><td class=path title="${esc(r.path)}">${esc(r.path)}</td><td><span class=badge>${esc(r.category)}</span></td><td>${esc(r.character||'—')}</td><td title="${esc(r.folder_path||'')}">${esc(r.folder||'—')}</td><td>${esc(r.role)}</td><td>${itemVisualBadge(r)}</td><td title="${esc(r.extension_description||'')}">${esc(r.ext||'—')}</td><td>${fmtBytes(r.size)}</td></tr>`).join('');$$('#assetRows tr').forEach(tr=>tr.onclick=()=>selectAsset(tr.dataset.path));S.catalogItems=d.items;if(S.view==='gallery')renderCatalogGallery();else $('#galleryMode').innerHTML='';applyView()}catch(e){if(e?.name!=='AbortError')throw e}finally{if(S.catalogAbort===controller)S.catalogAbort=null}}
