function fillSelect(id,arr,label,{extensions=false}={}){const el=$(id),cur=el.value;el.innerHTML=`<option value="">${label}</option>`+arr.slice(0,160).map(x=>{const blank=x.value==='';const value=blank&&extensions?'__NO_EXT__':x.value;let text=x.label||x.value;if(blank)text=extensions?'No extension':'(root)';if(extensions&&x.description)text=`${text} — ${x.description}`;return `<option value="${esc(value)}" title="${esc(x.description||x.value||'')}">${esc(text)} (${x.count})</option>`}).join('');if([...el.options].some(o=>o.value===cur))el.value=cur;else el.value=''}
