function scheduleSmdPreviewPoll(path,state){if(S.smdPreviewTimer){clearTimeout(S.smdPreviewTimer);S.smdPreviewTimer=null}const st=String(state?.status||'');if(!['QUEUED','RUNNING'].includes(st))return;const tick=async()=>{if(S.selected!==path)return;try{const d=await api('/api/smd-preview-status?path='+encodeURIComponent(path));if(S.selected!==path)return;const panel=$('#smdPreviewPanel');if(panel)panel.outerHTML=smdPreviewStateHtml(d.preview,path);bindPreviewFallbacks($('#detailPanel'));if(d.preview?.status==='FAILED'&&$('#smdPreviewRetry'))$('#smdPreviewRetry').onclick=()=>retrySmdPreview(path);if(['QUEUED','RUNNING'].includes(String(d.preview?.status||'')))S.smdPreviewTimer=setTimeout(tick,1200);else S.smdPreviewTimer=null}catch(e){if(S.selected===path)S.smdPreviewTimer=setTimeout(tick,1800)}};S.smdPreviewTimer=setTimeout(tick,900)}
