async function loadEntitiesInternal(force=false){const group=$('#entityGroup')?.value||'',q=$('#entitySearch')?.value.trim()||'',cacheKey=`${group}\0${q}`;if(!force&&S.entityListCache[cacheKey]){renderCachedEntities(S.entityListCache[cacheKey]);S.entityLoaded=true;return}if(S.entityAbort)S.entityAbort.abort();const controller=new AbortController();S.entityAbort=controller;try{const d=await api(`/api/entities?group=${encodeURIComponent(group)}&q=${encodeURIComponent(q)}&limit=1000`,{signal:controller.signal});if(controller.signal.aborted)return;const summary=`${Number(d.live_entity_count||0).toLocaleString()} related entities on the client`;const html=d.items.length?d.items.map(e=>{const tag={CHARACTER:'CHAR',ITEM:'ITEM',MONSTER:'MON',NPC:'NPC',EFFECT:'FX',MAP_FIELD:'MAP'}[e.semantic_group]||e.semantic_group;const preview=e.representative_preview?`<img loading="lazy" src="/api/preview?path=${encodeURIComponent(e.representative_preview)}" data-preview-fallback="icon" data-ext="${esc(tag)}">`:`<span class=ext-icon>${esc(tag)}</span>`;return `<div class="asset-card entity-card ${S.entity===e.entity_key?'selected':''}" data-entity-key="${esc(e.entity_key)}"><div class=thumb>${preview}</div><div class=card-body><div class=card-name title="${esc(e.display_name)}">${esc(e.display_name)}</div><div class=card-path title="${esc(e.folder_root||'')}">${esc(e.folder_root||'')}</div><div class=entity-stats>${esc(entityCountsText(e)||`${e.asset_count} assets`)}</div><div class=card-tags><span class=badge>${esc(e.semantic_group)}</span><span class=badge>${e.known_canonical_entity?'KNOWN':'LIVE'}</span>${e.registry_asset_count?`<span class=badge>REL ${e.registry_asset_count}</span>`:''}${e.semantic_group==='ITEM'&&Number(e.visual_bundle_member_count||1)>1?`<span class=badge>VISUAL ×${Number(e.visual_bundle_member_count)}</span>`:''}</div></div></div>`}).join(''):'<div class=empty>No entities match these filters.</div>';S.entityListCache[cacheKey]={summary,html};renderCachedEntities(S.entityListCache[cacheKey]);S.entityLoaded=true}catch(e){if(e?.name!=='AbortError')$('#entityGrid').innerHTML=`<div class=empty>${esc(e.message)}</div>`}finally{if(S.entityAbort===controller)S.entityAbort=null}}
