function switchServerWorkflow(workflow){
  const allowed=new Set(['config','diagnostics','census','validation','evidence','activity']);
  workflow=allowed.has(workflow)?workflow:'config';
  S.serverWorkflow=workflow;localStorage.setItem('ptAssetServerWorkflow',workflow);
  $$('[data-server-workflow]').forEach(b=>{const active=b.dataset.serverWorkflow===workflow;b.classList.toggle('active',active);b.setAttribute('aria-selected',active?'true':'false')});
  $$('[data-server-workflow-pane]').forEach(p=>p.classList.toggle('active',p.dataset.serverWorkflowPane===workflow));
  if(workflow==='activity')loadServerActivity();
  if(workflow==='evidence')loadAssetContracts();
  if(workflow==='census')loadGeneralCensus();
}
function openLegacyFromServer(target='world'){
  setTab('legacy');
  switchLegacyTask(target==='world'?'world':target);
  if(target==='world')loadLegacyExplorer();
}
