    $$('[data-server-job-console]').forEach(b=>b.onclick=e=>{e.stopPropagation();showServerJob(b.dataset.serverJobConsole)});
    $$('[data-server-job-result]').forEach(b=>b.onclick=async e=>{e.stopPropagation();const j=jobs.find(x=>x.id===b.dataset.serverJobResult);if(j)await openServerJobResult(j)});
    $$('[data-server-job]').forEach(row=>row.onclick=()=>showServerJob(row.dataset.serverJob));
