function switchClientWorkflow(workflow){
  const allowed=new Set(['overview','diagnostics','census','validation','enhancement','activity']);
  workflow=allowed.has(workflow)?workflow:'overview';
  S.clientWorkflow=workflow;localStorage.setItem('ptAssetClientWorkflow',workflow);
  $$('[data-client-workflow]').forEach(b=>{const active=b.dataset.clientWorkflow===workflow;b.classList.toggle('active',active);b.setAttribute('aria-selected',active?'true':'false')});
  $$('[data-client-workflow-pane]').forEach(p=>p.classList.toggle('active',p.dataset.clientWorkflowPane===workflow));
  if(workflow==='activity')loadClientActivity();
  if(workflow==='census')loadClientCensus();
  if(workflow==='validation')loadClientEnrichmentIssues();
}
