    $('#clientActivityList').innerHTML=jobs.length?jobs.map(j=>{const active=['QUEUED','RUNNING','CANCELLING'].includes(j.status),hasResult=!active&&Boolean(j.workflow);return `<div class="server-job ${S.clientJob===j.id?'selected':''}" data-client-job="${esc(j.id)}"><div class="server-job-state"><span class="status ${esc(j.status)}">${esc(j.status)}</span><small>${new Date(j.created_at*1000).toLocaleString()}</small></div><div class="server-job-main"><b>${esc(clientJobActionLabel(j.action))}</b><small>${esc(clientWorkflowLabel(j.workflow))}${j.finished_at?` · terminou ${new Date(j.finished_at*1000).toLocaleString()}`:''}</small><code title="${esc(j.command_display||'')}">${esc(j.command_display||'')}</code></div><div class="server-job-actions"><button class="btn small" data-client-job-console="${esc(j.id)}">${active?'Acompanhar':'Console'}</button><button class="btn small" data-client-job-result="${esc(j.id)}" ${hasResult?'':'disabled'}>Open result</button></div></div>`}).join(''):'<div class=empty>No task started in Client / Enrichment.</div>';
