async function showClientJob(id){
  if(!id)return;S.clientJob=id;clearInterval(S.clientJobPoll);S.clientJobPoll=null;
  const poll=async()=>{
    try{
      const d=await api('/api/job?id='+encodeURIComponent(id)),j=d.job,active=['QUEUED','RUNNING','CANCELLING'].includes(j.status);
      if($('#clientConsoleStatus'))$('#clientConsoleStatus').textContent=`${clientJobActionLabel(j.action)} · ${j.status}`;
      if($('#clientConsole')){$('#clientConsole').textContent=j.tail||j.command_display||'';$('#clientConsole').scrollTop=$('#clientConsole').scrollHeight}
      if($('#clientCancelJobBtn')){$('#clientCancelJobBtn').style.display=active?'inline-block':'none';$('#clientCancelJobBtn').disabled=j.status==='CANCELLING'}
      if($('#clientOpenResultBtn')){$('#clientOpenResultBtn').disabled=active||!j.workflow;$('#clientOpenResultBtn').dataset.job=id}
      if(!active){clearInterval(S.clientJobPoll);S.clientJobPoll=null;await loadClientEnrichment();await loadClientActivity()}
      return j;
    }catch(e){if($('#clientConsoleStatus'))$('#clientConsoleStatus').textContent='Error loading job';clearInterval(S.clientJobPoll);S.clientJobPoll=null;return null}
  };
  const j=await poll();if(j&&['QUEUED','RUNNING','CANCELLING'].includes(j.status))S.clientJobPoll=setInterval(poll,900);
}
