  const stateLabel={BLOCKED:'BLOCKED · fix the configuration',RUNNING:'RUNNING · see Server → Activity',REPORT_FRESH:'CURRENT REPORT · ready to read',REPORT_STALE:'STALE REPORT · run again',READY_TO_RUN:'READY TO RUN'}[state]||state;
