async function runEnhancementBatch(mode){try{let endpoint='',body={};if(mode==='run'){if(!(await armBuildForEnhancement()))return;if(!confirm('Generate AI enhancement for ALL supported client textures, including UI/atlases?\n\nThis may consume substantial time and disk space. The source client will not be modified at this stage.'))return;const scale=prompt('Escala global: 2, 3 ou 4','4');if(scale===null)return;if(!['2','3','4'].includes(scale.trim())){toast('Use 2, 3 ou 4');return}endpoint='/api/enhancement/batch-run';body={scale:scale.trim(),backend:'realesrgan',profile:'detail',gpu:0,model:'realesrgan-x4plus'}}else if(mode==='resume'){if(!(await armBuildForEnhancement()))return;if(!confirm('Resume the latest enhancement run? Candidates already validated by hash will be reused; failures/pending items will be processed again.'))return;endpoint='/api/enhancement/batch-resume'}else if(mode==='publish'){if(!(await armDeployForEnhancement()))return;if(!confirm('PUBLISH the latest complete enhancement batch to the client?\n\nBefore the first write, ALL candidates will be checked against the current hash. Each asset will have its own backup. A mid-run failure triggers automatic rollback of what this batch already published.'))return;endpoint='/api/enhancement/batch-publish'}else if(mode==='restore'){if(!(await armDeployForEnhancement()))return;if(!confirm('ROLL BACK the latest published enhancement batch?\n\nRestore starts only if all assets still match the published hash exactly and all backups are valid.'))return;endpoint='/api/enhancement/batch-restore'}else return;const d=await api(endpoint,{method:'POST',body});S.job=d.job.id;S.clientJob=d.job.id;if(mode!=='run'){S.boot.deploy_armed=false;S.boot.deploy_armed_until=0}$('#clientEnhancementBatchState').textContent=`QUEUED · ${d.mode}`;toast(mode==='run'?'Global enhancement started':mode==='resume'?'Enhancement resume started':mode==='publish'?'Batch publish started':'Batch rollback started');switchClientWorkflow('activity');await loadClientActivity();showClientJob(d.job.id)}catch(e){toast(e.message)}}
