function renderCompareReport(r){const s=r.summary||{},rows=(r.rows||[]),shown=rows.slice(0,500);$('#compareStatus').textContent=`PASS · ${Number(s.difference_path_count||0).toLocaleString()} differences`;const metrics=[['Left',s.left_file_count],['Right',s.right_file_count],['Left only',s.only_left_count],['Right only',s.only_right_count],['Different',s.difference_path_count]];const table=shown.length?`<div class=compare-table><table><thead><tr><th>Status</th><th>Category</th><th>Ext</th><th>Path</th><th>Size A</th><th>Size B</th></tr></thead><tbody>${shown.map(row=>{const open=compareOpenPath(r,row);const path=row.left_path||row.right_path||row.key;return `<tr ${open?`data-open-asset="${esc(open)}" class=compare-row-clickable`:''}><td><span class="status ${esc(row.status)}">${esc(row.status)}</span></td><td>${esc(row.category||'—')}</td><td>${esc(row.extension||'—')}</td><td class=path title="${esc(path)}">${esc(path)}</td><td>${row.left_size==null?'—':fmtBytes(row.left_size)}</td><td>${row.right_size==null?'—':fmtBytes(row.right_size)}</td></tr>`}).join('')}</tbody></table></div>`:'<div class=empty>No rows to display with the current filters.</div>';$('#compareResult').innerHTML=`<div class=compare-summary>${metrics.map(([label,value])=>`<div class=metric><b>${Number(value||0).toLocaleString()}</b><span>${esc(label)}</span></div>`).join('')}</div><div class=compare-note>${r.content_hash?'SHA-256 active':'Fast comparison by path/size'} · ${r.differences_only?'differences only':'all rows'} · showing ${shown.length.toLocaleString()} of ${rows.length.toLocaleString()} report rows.</div>${table}`;$$('[data-open-asset]').forEach(x=>x.onclick=async()=>{setTab('catalog');await selectAsset(x.dataset.openAsset)})}
