function configureLegacyEditorForTask(task){const sel=$('#legacyAuthoringKind'),kinds=legacyKindsForTask(task);if(!sel)return;if(!kinds.length){sel.innerHTML='';return}const current=sel.value;sel.innerHTML=kinds.map(k=>`<option value="${k}">${esc(({ITEM:'ITEM',MONSTER:'MONSTER',NPC:'NPC',SPM:'SPM',SPP:'SPP',SPC:'SPC'})[k])}</option>`).join('');if(kinds.includes(current))sel.value=current;else sel.value=kinds[0];sel.classList.toggle('hidden',kinds.length===1)}
function syncLegacyAuthoringUi(){const kind=$('#legacyAuthoringKind')?.value||'',mode=$('#legacyAuthoringMode')?.value||'EDIT';if($('#legacyAuthoringTitle'))$('#legacyAuthoringTitle').textContent=legacyAuthoringTitle(kind,mode);const itemHelper=$('#legacyAuthoringItemHelper');if(itemHelper)itemHelper.classList.toggle('hidden',!['MONSTER','NPC'].includes(kind));const entityHelper=$('#legacyAuthoringEntityHelper');if(entityHelper)entityHelper.classList.toggle('hidden',!['SPM','SPC'].includes(kind));syncLegacyAuthoringCatalogHelper();const pub=$('#legacyAuthoringPublishBtn');if(pub){pub.disabled=!S.legacyAuthoringManifest;pub.title=S.legacyAuthoringManifest?'Publish o manifest staged desta tarefa':'Run Stage for this task before publishing'}}
