async function loadLegacySelections(refresh=false){try{const d=await api('/api/legacy-ops/selections'+(refresh?'?refresh=1':''));renderLegacySelections(d.result||d);return d.result||d}catch(e){toast('Listas Legacy: '+e.message);return null}}
function legacySelectedItem(value){const v=String(value||'');return (semanticCatalog().items||[]).find(x=>String(x.canonical_id||'').toLowerCase()===v.toLowerCase())||(S.legacySelections?.items||[]).find(x=>String(x.code||'').toUpperCase()===v.toUpperCase())||null}
