async function useLegacyCatalogEntry(){const row=legacySelectedCatalogEntry();if(!row){toast('Select a semantic catalog record');return}const kind=$('#legacyAuthoringKind')?.value||'ITEM',mode=$('#legacyAuthoringMode')?.value||'EDIT';let spec;try{spec=JSON.parse($('#legacyAuthoringSpec')?.value||'{}')}catch{spec=legacyAuthoringTemplate()}spec.kind=kind;spec.mode=mode;spec.semantic_ref={canonical_id:row.canonical_id,category:row.category,display_name:row.display_name,internal_name:row.internal_name};const mappedPath=legacyAuthoringCatalogPath(row,kind);if(mappedPath){$('#legacyAuthoringPath').value=mappedPath;spec.path=mappedPath}if(kind==='ITEM'){if(mode==='CREATE'){const fields=spec.fields||(spec.payload?.fields)||(spec.fields={});fields.code=row.code||row.internal_name||'';if(row.display_name)fields.name=row.display_name}}else if(kind==='MONSTER'){if(mode==='CREATE'){spec.payload=spec.payload||{fields:{},drops:[]};spec.payload.fields=spec.payload.fields||{};spec.payload.fields.name=row.display_name||row.internal_name||'';if(row.model_file)spec.payload.fields.model_file=row.model_file;if(row.level!=null)spec.payload.fields.level=row.level}}else if(kind==='NPC'){if(mode==='CREATE'){spec.payload=spec.payload||{fields:{},dialogs:[],shops:{weapon:[],defence:[],etc:[]}};spec.payload.fields=spec.payload.fields||{};spec.payload.fields.name=row.display_name||row.internal_name||'';if(row.model_file)spec.payload.fields.model_file=row.model_file}}$('#legacyAuthoringSpec').value=JSON.stringify(spec,null,2);$('#legacyAuthoringState').textContent=`${kind} · ${row.display_name||row.canonical_id} · ${row.confidence||'without confidence'}`;if(mode==='EDIT'&&mappedPath)await inspectLegacyAuthoring();else toast(`Mapping ${row.canonical_id} applied to CREATE`)}
function addLegacySemanticRelatedRef(spec,role,row){if(!row?.canonical_id)return;spec.semantic_related_refs=Array.isArray(spec.semantic_related_refs)?spec.semantic_related_refs:[];if(!spec.semantic_related_refs.some(x=>String(x?.role||'').toUpperCase()===String(role).toUpperCase()&&String(x?.canonical_id||'').toLowerCase()===String(row.canonical_id).toLowerCase()))spec.semantic_related_refs.push({role,canonical_id:row.canonical_id})}
function insertLegacyItemIntoSpec(){const selected=$('#legacyAuthoringItemCode')?.value||'';if(!selected){toast('Select a related item');return}const item=legacySelectedItem(selected);const code=String(item?.code||item?.internal_name||selected);let spec;try{spec=JSON.parse($('#legacyAuthoringSpec')?.value||'{}')}catch(e){toast('Invalid JSON: '+e.message);return}const kind=$('#legacyAuthoringKind')?.value||'ITEM';if(kind==='MONSTER'){if(spec.payload){spec.payload.drops=spec.payload.drops||[];if(!spec.payload.drops.length)spec.payload.drops.push({percentage:100,items:[code]});else{const row=spec.payload.drops[0];row.items=Array.isArray(row.items)?row.items:[];if(!row.items.includes(code))row.items.push(code)}}else{spec.patch=spec.patch||{};spec.patch.drops=spec.patch.drops||[{percentage:100,items:[]}];const row=spec.patch.drops[0];row.items=Array.isArray(row.items)?row.items:[];if(!row.items.includes(code))row.items.push(code)}addLegacySemanticRelatedRef(spec,'ITEM_REFERENCE',item)}else if(kind==='NPC'){const root=spec.payload||spec.patch||(spec.patch={});root.shops=root.shops||{weapon:[],defence:[],etc:[]};root.shops.weapon=Array.isArray(root.shops.weapon)?root.shops.weapon:[];if(!root.shops.weapon.includes(code))root.shops.weapon.push(code);addLegacySemanticRelatedRef(spec,'ITEM_REFERENCE',item)}$('#legacyAuthoringSpec').value=JSON.stringify(spec,null,2);toast(`${item?.display_name||code} (${code}) inserted into the spec`)}
function insertLegacyEntityIntoSpec(){const kind=$('#legacyAuthoringKind')?.value||'',id=$('#legacyAuthoringEntityRef')?.value||'';if(!id){toast('Select the related entity');return}const rows=kind==='SPM'?(semanticCatalog().mobs||[]):(semanticCatalog().npcs||[]),row=rows.find(x=>String(x.canonical_id||'').toLowerCase()===String(id).toLowerCase());if(!row){toast('Entidade mapeada not found');return}let spec;try{spec=JSON.parse($('#legacyAuthoringSpec')?.value||'{}')}catch(e){toast('Invalid JSON: '+e.message);return}const mode=$('#legacyAuthoringMode')?.value||'EDIT';if(kind==='SPM'){if(mode==='CREATE'){spec.payload=spec.payload||{};spec.payload.actors=Array.isArray(spec.payload.actors)?spec.payload.actors:[];spec.payload.actors.push({name:row.display_name||row.internal_name,weight:100})}else{spec.patch={action:'ADD_ACTOR',name:row.display_name||row.internal_name,weight:100}}addLegacySemanticRelatedRef(spec,'ACTOR',row)}else if(kind==='SPC'){const rec={name:row.display_name||row.internal_name,model_ini:row.model_file||'',server_npc:row.logical_path||'',x:0,y:0,z:0};if(mode==='CREATE'){spec.payload=spec.payload||{};spec.payload.records=Array.isArray(spec.payload.records)?spec.payload.records:[];spec.payload.records.push({index:spec.payload.records.length,...rec})}else{spec.patch={action:'ADD',index:-1,record:rec}}addLegacySemanticRelatedRef(spec,'FIXED_NPC',row)}$('#legacyAuthoringSpec').value=JSON.stringify(spec,null,2);toast(`${row.display_name||row.internal_name} inserido no ${kind}`)}
function renderLegacyOpsStatus(d){const tasks=d?.tasks||[];const by=id=>tasks.find(x=>x.id===id);const c=by('character_account'),p=by('items_postbox'),a=by('admin_local'),db=d?.database||a?.database||{};if($('#legacyOpsCharacterState'))$('#legacyOpsCharacterState').textContent=c?`${c.status} · userdata + userinfo`:'unavailable';if($('#legacyPostboxState'))$('#legacyPostboxState').textContent=p?`${p.status} · Postbox + serial scan`:'unavailable';if($('#legacyAdminState'))$('#legacyAdminState').textContent=a?`${a.status} · localhost + SQLite`:'unavailable';if($('#legacyAdminSummary'))$('#legacyAdminSummary').innerHTML=a?legacyTaskStatusCard(a):'<div class="empty">Local admin unavailable.</div>';const candidates=(db.candidates||[]).map(x=>({value:x.path,label:`${x.path} · ${Number(x.score||0)} known tables${(x.matched_tables||[]).length?' · '+x.matched_tables.join(', '):''}`}));if(db.path&&!candidates.some(x=>x.value===db.path))candidates.unshift({value:db.path,label:`${db.path} · ${db.selection_basis||'SQLite'}`});legacySelectOptions($('#legacyDatabasePath'),candidates,{placeholder:'Select the SQLite database'});if($('#legacyDatabasePath')&&db.path)$('#legacyDatabasePath').value=db.path;S.legacyOpsStatus=d}
