function legacyPlanReady(saved){return saved?.apply_supported===true&&String(saved?.plan?.status||'').toUpperCase()==='READY'}
function showLegacyOpsPlan(saved){S.legacyOpsPlanId=saved?.plan_id||null;S.legacyOpsSavedPlan=saved||null;const panel=$('#legacyOpsPlanPanel'),out=$('#legacyOpsPlanResult'),state=$('#legacyOpsPlanState'),confirm=$('#legacyOpsConfirmation'),apply=$('#legacyOpsApplyBtn');if(panel)panel.classList.remove('hidden');if(out)out.textContent=legacyOpsJson(saved);const phrase=saved?.required_confirmation||'';if(confirm){confirm.value='';confirm.placeholder=phrase||'this operation is plan-only'}if(state)state.textContent=legacyPlanReady(saved)?`READY · confirme “${phrase}”`:saved?.apply_supported===false?'PLAN ONLY · no write will be executed':`${saved?.plan?.status||'REVIEW'} · fix the blockers before applying`;if(apply){apply.disabled=!legacyPlanReady(saved);apply.textContent=legacyPlanReady(saved)?'Apply reviewed plan':'Apply unavailable'}panel?.scrollIntoView({behavior:'smooth',block:'start'})}
function validateLegacyOperation(operation,p={}){const need=(v,msg)=>{if(String(v??'').trim()==='')throw new Error(msg)};switch(String(operation||'').toUpperCase()){case'CHARACTER_LEVEL':need(p.character,'Select the character');if(!Number.isFinite(Number(p.level))||Number(p.level)<1)throw new Error('Level must be greater than or equal to 1');break;case'CHARACTER_FIELDS':case'CHARACTER_EXPERT_FIELDS':need(p.character,'Select the character');break;case'CHARACTER_RENAME':need(p.old_name,'Select the character');need(p.new_name,'Enter the new character name');break;case'ACCOUNT_RENAME':need(p.old_account,'Select the account');need(p.new_account,'Enter the new account name');break;case'ACCOUNT_GRAPH_COPY':need(p.source_server_root,'Enter the source server');need(p.account,'Select the account');break;case'ITEM_DISTRIBUTE':need(p.account,'Select the account');need(p.character,'Select the character');need(p.item_code,'Select the item');if(Number(p.quantity)<1)throw new Error('Quantity must be greater than or equal to 1');break;case'INVENTORY_ITEM_DELETE':need(p.key,'Select the identity');if(Number(p.record_index)<0)throw new Error('Invalid record index');break;case'INVENTORY_ITEM_BATCH_DELETE':need(p.key,'Select the identity');if(!(p.record_indices||[]).length)throw new Error('Enter at least one record index');break;case'BPRANK_MARK':need(p.char_name,'Select the character');need(p.db_path,'Select the SQLite database');break;case'ACCOUNT_BLOCK':need(p.account,'Select the account');need(p.db_path,'Select the SQLite database');break;case'SOD_UPDATE':need(p.db_path,'Select the SQLite database');break}return true}
async function planLegacyOps(operation,payload,resultSelector){try{validateLegacyOperation(operation,payload||{});const d=await api('/api/legacy-ops/plan',{method:'POST',body:{operation,payload}});showLegacyOpsPlan(d.result);if(resultSelector)legacyOpsSet(resultSelector,d.result);toast(d.result?.apply_supported?'Plan persisted; review before applying':'Plan generated; the operation cannot be applied from this screen');return d.result}catch(e){const err={status:'ERROR',http_status:e.httpStatus||null,error:e.payload?.error||'VALIDATION_OR_REQUEST_FAILED',detail:e.message};if(resultSelector)legacyOpsSet(resultSelector,err);toast(e.message);return null}}
