async function compareCanonicalMapProfiles(){const id=$('#canonicalV211Id')?.value.trim()||$('#canonicalV211Search')?.value.trim()||'';if(!id){toast('Enter a canonical map ID first');return}try{const d=await api('/api/canonical/map-compare?canonical_id='+encodeURIComponent(id));$('#canonicalV211BrowserResult').textContent=JSON.stringify(d.result,null,2)}catch(e){$('#canonicalV211BrowserResult').textContent=e.message;toast(e.message)}}
async function stageCanonicalV211(){try{const spec=canonicalV211Spec();$('#canonicalV211Result').textContent='Staging complete canonical tree, validating schemas, compiling and inspecting packs…';const d=await api('/api/canonical/stage',{method:'POST',body:{spec,run_validation:true,run_build:true}});S.canonicalV211Manifest=d.result?.manifest||null;const mp=d.result?.manifest?.manifest||'';if($('#canonicalV211Manifest'))$('#canonicalV211Manifest').value=mp;$('#canonicalV211Result').textContent=JSON.stringify(d.result,null,2);toast('Canonical stage complete')}catch(e){$('#canonicalV211Result').textContent=e.message;toast(e.message)}}
async function canonicalV211Publish(action){const path=$('#canonicalV211Manifest')?.value.trim()||'';if(!path){toast('Stage first or provide a manifest path');return}const confirm=$('#canonicalV211Confirm')?.value||'';try{const d=await api('/api/canonical/'+action,{method:'POST',body:{manifest:path,confirm}});$('#canonicalV211Result').textContent=JSON.stringify(d.result,null,2);if(S.boot)S.boot.server_deploy_armed=false;await loadCanonicalV211();toast(action==='restore'?'Canonical transaction restored':'Canonical publish phase complete')}catch(e){$('#canonicalV211Result').textContent=e.message;toast(e.message)}}
function syncCanonicalV211Kind(){const kind=$('#canonicalV211Kind')?.value||'ITEM',patch=$('#canonicalV211Patch');if(!patch)return;if(['ITEM','MONSTER','NPC'].includes(kind))patch.value='{\n  "fields": {}\n}';else patch.value='{\n  "set": {}\n}';if($('#canonicalV211Profile'))$('#canonicalV211Profile').disabled=kind!=='MAP'}
function bindCanonicalV211(){if($('#canonicalV211Refresh'))$('#canonicalV211Refresh').onclick=loadCanonicalV211;if($('#canonicalV211Browse'))$('#canonicalV211Browse').onclick=browseCanonicalV211;if($('#canonicalV211ItemProfiles'))$('#canonicalV211ItemProfiles').onclick=browseCanonicalItemProfiles;if($('#canonicalV211GameplayConfig'))$('#canonicalV211GameplayConfig').onclick=browseCanonicalGameplayConfig;if($('#canonicalV211Localization'))$('#canonicalV211Localization').onclick=browseCanonicalLocalization;if($('#canonicalV211References'))$('#canonicalV211References').onclick=browseCanonicalReferences;if($('#canonicalV211Domains'))$('#canonicalV211Domains').onclick=browseCanonicalDomains;if($('#canonicalV211CompareMap'))$('#canonicalV211CompareMap').onclick=compareCanonicalMapProfiles;if($('#canonicalV211Stage'))$('#canonicalV211Stage').onclick=stageCanonicalV211;if($('#canonicalV211PublishSource'))$('#canonicalV211PublishSource').onclick=()=>canonicalV211Publish('publish-source');if($('#canonicalV211PublishPacks'))$('#canonicalV211PublishPacks').onclick=()=>canonicalV211Publish('publish-packs');if($('#canonicalV211DeployRuntime'))$('#canonicalV211DeployRuntime').onclick=()=>canonicalV211Publish('deploy-runtime');if($('#canonicalV211Restore'))$('#canonicalV211Restore').onclick=()=>canonicalV211Publish('restore');if($('#canonicalV211Kind'))$('#canonicalV211Kind').onchange=syncCanonicalV211Kind;syncCanonicalV211Kind()}
async function loadLegacyManagement(){try{const d=await api('/api/legacy-management');renderLegacyAuditMetrics(d);await Promise.all([loadCanonicalV211(),loadLegacyAuthoringGuide(),loadLegacyOpsStatus(),loadLegacySelections(false)]);switchLegacyTask(S.legacyTask||localStorage.getItem('ptAssetLegacyTask')||'item');if(S.legacyTask==='world')await loadLegacyExplorer()}catch(e){if($('#legacyAuditState'))$('#legacyAuditState').textContent='Error';toast(e.message)}}
async function runLegacyAudit(){try{const d=await api('/api/legacy-management/audit',{method:'POST',body:{management_root:$('#legacyManagementRoot')?.value.trim()||'',tutorial_root:$('#legacyTutorialRoot')?.value.trim()||'',sample_limit:Number($('#legacySampleLimit').value||80)}});S.job=d.job.id;$('#legacyAuditState').textContent='QUEUED · legacy_management_audit';toast('Legacy Management audit started');pollLegacyAudit(d.job.id)}catch(e){toast(e.message)}}
async function pollLegacyAudit(id){clearInterval(S.legacyPoll);const poll=async()=>{try{const d=await api('/api/job?id='+encodeURIComponent(id)),j=d.job;$('#legacyAuditState').textContent=`${j.status} · ${j.action}`;if(['PASS','FAIL','ERROR','CANCELLED'].includes(j.status)){clearInterval(S.legacyPoll);S.legacyPoll=null;await loadLegacyManagement();if(j.status==='PASS'){switchLegacyTask('world');await loadLegacyExplorer()}toast(j.status==='PASS'?'World Closure built; results updated':`Management Audit: ${j.status}`)}}catch(e){clearInterval(S.legacyPoll);S.legacyPoll=null;toast(e.message)}};await poll();if(S.legacyPoll===null&&/^(PASS|FAIL|ERROR|CANCELLED)/.test($('#legacyAuditState').textContent))return;S.legacyPoll=setInterval(poll,1200)}
function renderLegacyItem(d){const rt=d.runtime_item_contract||{},m=(rt.matches||[])[0],pc=(d.physical_client_closure||[])[0];$('#legacyItemState').textContent=`${d.code||'—'} · ${rt.status||'REVIEW'}`;if(!m){$('#legacyItemResult').innerHTML=`<div class=legacy-item-card><h3>${esc(d.code||'—')}</h3><p>${legacyStatusChip(rt.status||'RUNTIME_CODE_NOT_VERIFIED')}</p><p>This code does not exist in the source-verified runtime catalog. The application uses historical classifications internally when useful, but you do not need to choose a prefix/category manually.</p><p class=micro>Do not create OpenItem for a new code until the sITEM registry is implemented/certified.</p></div>`;return}const paths=m.expected_client_paths||{};$('#legacyItemResult').innerHTML=`<div class=legacy-item-card><div class=legacy-item-title><h3>${esc(d.code)}</h3>${legacyStatusChip(rt.status)}</div><div class=legacy-item-columns><dl><dt>Runtime code</dt><dd><code>${esc(m.numeric_code_hex||'—')}</code></dd><dt>Icon folder</dt><dd>${esc(m.item_file_path||'—')}</dd><dt>Visual identifier</dt><dd><code>${esc(m.dorp_item||'—')}</code></dd><dt>Class</dt><dd>${esc(m.class_value)}</dd><dt>Model position</dt><dd>${esc(m.set_model_posi)}</dd><dt>Sound</dt><dd>${esc(m.sound_index)}</dd><dt>Weapon class</dt><dd>${esc(m.weapon_class)}</dd></dl><dl><dt>Expected icon</dt><dd><code>${esc(paths.inventory_icon||'—')}</code><br>${legacyStatusChip(pc?.inventory_icon?.status)}</dd><dt>Ground model</dt><dd><code>${esc(paths.drop_model_ase||'—')}</code><br>${legacyStatusChip(pc?.drop_model_ase?.status)}</dd><dt>New sITEM registration</dt><dd>${legacyStatusChip(m.source_semantics?.writer_authorized?'AUTHORIZED':'BLOCKED')}</dd></dl></div></div>`}
async function lookupLegacyItem(){const code=$('#legacyItemCode').value.trim();if(!code){toast('Enter an item code');return}try{const d=await api('/api/legacy-management/item?code='+encodeURIComponent(code));renderLegacyItem(d)}catch(e){toast(e.message)}}
function legacyExplorerColumns(section){if(section==='maps')return [['status','Status'],['spm','SPM'],['actor_count','Actors'],['item_codes','Items resolvidos'],['review_summary','What to do']];if(section==='definitions')return [['status','Status'],['kind','Type'],['definition','Definition'],['drop_item_reference_count','Drops item'],['review_summary','What to do']];return [['status','Status'],['code','Code'],['closures','DorpItem / assets'],['review_summary','What to do']]}
function legacyCell(row,key){const v=row?.[key];if(key==='status')return `${legacyStatusChip(v)}${row?.review_required?'<small class=review-inline>see reason →</small>':''}`;if(key==='closures')return esc((v||[]).map(x=>`${x.dorp_item||'—'} · icon ${x.inventory_icon?.status||'—'} · ground ${x.drop_model_ase?.status||'—'}`).join(' | ')||'—');if(key==='drop_item_reference_count'){if(String(row?.kind||'').toUpperCase()!=='MONSTER')return '<span class=muted>n/a</span>';if(v==null)return '<span class=review-inline>audit again</span>';return `${esc(v)}${Number(v)===0?'<small class=review-inline title="0 does not prove no drop">does not prove “no drop”</small>':''}`}if(key==='review_summary')return esc(v||'No pending issue detected.');if(Array.isArray(v))return esc(v.map(x=>typeof x==='object'?JSON.stringify(x):String(x)).join(', '));return esc(v??'—')}
function legacyReviewActions(row){const actions=row?.review_actions||[];return actions.length?`<div class=legacy-review-actions>${actions.map((a,i)=>`<button class="btn ${i===0?'primary':''}" data-legacy-review-action="${i}">${esc(a.label||'Open')}</button>`).join('')}</div>`:''}
async function runLegacyReviewAction(row,index){const a=(row?.review_actions||[])[Number(index)];if(!a)return;if(a.kind==='ITEM_LOOKUP'){switchLegacyTask('item');$('#legacyItemCode').value=a.code||'';await lookupLegacyItem();$('#legacyItemResult')?.scrollIntoView({behavior:'smooth',block:'start'});return}if(a.kind==='AUTHORING'){await legacyAuthoringOpenReviewTarget(a.authoring_kind,a.path);return}toast(`Unsupported review action: ${a.kind}`)}
async function legacyAuthoringOpenReviewTarget(kind,path){kind=String(kind||'').toUpperCase();if(!kind||!path){toast('Incomplete authoring target');return}switchLegacyTask(legacyTaskForKind(kind));configureLegacyEditorForTask(legacyTaskForKind(kind));$('#legacyAuthoringKind').value=kind;$('#legacyAuthoringMode').value='EDIT';$('#legacyAuthoringPath').value=path;S.legacyAuthoringManifest=null;$('#legacyAuthoringSpec').value=JSON.stringify(legacyAuthoringTemplate(),null,2);$('#legacyAuthoringState').textContent=`${kind} · loaded explicitly from REVIEW`;syncLegacyAuthoringUi();await inspectLegacyAuthoring();$('#legacyAuthoringPanel')?.scrollIntoView({behavior:'smooth',block:'start'})}
function renderLegacyExplorerDetail(row){if(!row){$('#legacyExplorerDetail').innerHTML='<div class=empty>Select a row. REVIEW shows the reason and next action; nothing opens in the editor automatically.</div>';return}const reasons=row.review_reasons||[],zhoon=(row.zhoon_references||[]),kind=String(row.kind||'').toUpperCase();let domainInfo='';if(kind==='MONSTER'){const broad=Number(row.item_reference_count||0),drops=row.drop_item_reference_count;domainInfo=`<section class=legacy-review-info><h4>Items and drops</h4><p><b>Item drops:</b> ${drops==null?'old report; audit again':esc(drops)}. ${esc(row.drop_note||'')}</p><p><b>Item references in file:</b> ${broad}. ${esc(row.item_reference_note||'')}</p>${zhoon.length?`<p><b>.zhoon:</b> ${esc(zhoon.join(', '))}. ${esc(row.zhoon_note||'')}</p>`:''}</section>`}else if(kind==='NPC'){domainInfo=`<section class=legacy-review-info><h4>Item references</h4><p><b>Detected:</b> ${Number(row.item_reference_count||0)}. ${esc(row.item_reference_note||'')}</p>${zhoon.length?`<p><b>.zhoon:</b> ${esc(zhoon.join(', '))}. ${esc(row.zhoon_note||'')}</p>`:''}</section>`}const review=row.review_required?`<section class=legacy-review-box><h4>Why is this in REVIEW?</h4>${reasons.length?reasons.map(r=>`<div class=legacy-review-reason><b>${esc(r.title||r.code)}</b><p>${esc(r.detail||'')}</p><code>${esc(r.code||'')}</code></div>`).join(''):'<p>The report marked REVIEW but did not provide a structured cause. Audit again with the current version.</p>'}${legacyReviewActions(row)}</section>`:`<section class=legacy-review-ok><b>No closure issue detected in this row.</b><p>${esc(row.review_summary||'')}</p>${legacyReviewActions(row)}</section>`;$('#legacyExplorerDetail').innerHTML=`<h3>${esc(row.code||row.spm||row.definition||'Details')}</h3>${review}${domainInfo}<details class=legacy-technical-detail><summary>Technical details</summary><pre class=legacy-json>${esc(JSON.stringify(row,null,2))}</pre></details>`;$$('[data-legacy-review-action]').forEach(b=>b.onclick=()=>runLegacyReviewAction(row,b.dataset.legacyReviewAction))}
async function loadLegacyExplorer(){const section=$('#legacyExplorerSection')?.value||'items',q=$('#legacyExplorerSearch')?.value||'',status=$('#legacyExplorerStatus')?.value||'';try{const d=await api(`/api/legacy-management/report?section=${encodeURIComponent(section)}&q=${encodeURIComponent(q)}&status=${encodeURIComponent(status)}&limit=200`);$('#legacyExplorerState').textContent=d.status==='PASS'?`${d.filtered_rows}/${d.total_rows} records`:d.status;const cols=legacyExplorerColumns(section);$('#legacyExplorerHead').innerHTML='<tr>'+cols.map(x=>`<th>${esc(x[1])}</th>`).join('')+'</tr>';$('#legacyExplorerRows').innerHTML=(d.rows||[]).map((r,i)=>`<tr data-legacy-row="${i}">${cols.map(([k])=>`<td>${legacyCell(r,k)}</td>`).join('')}</tr>`).join('')||`<tr><td colspan="${cols.length}"><div class=empty>${d.status==='NO_REPORT'?'Run the Management audit to generate the report.':'No records match the current filters.'}</div></td></tr>`;S.legacyRows=d.rows||[];$$('[data-legacy-row]').forEach(tr=>tr.onclick=async()=>{const row=S.legacyRows[Number(tr.dataset.legacyRow)];$$('[data-legacy-row]').forEach(x=>x.classList.toggle('selected',x===tr));renderLegacyExplorerDetail(row)})}catch(e){$('#legacyExplorerState').textContent='Error';toast(e.message)}}
function legacyAuthoringDefaultPath(kind){return ({ITEM:'GameServer/OpenItem/WA121.txt',MONSTER:'GameServer/Monster/NewMonster.inf',NPC:'GameServer/NPC/NewNPC.npc',SPM:'GameServer/Field/field.spm',SPP:'GameServer/Field/field.spp',SPC:'GameServer/Field/field.spc'})[kind]||''}
function legacyAuthoringTemplate(){const kind=$('#legacyAuthoringKind')?.value||'ITEM',mode=$('#legacyAuthoringMode')?.value||'EDIT',path=$('#legacyAuthoringPath')?.value.trim()||legacyAuthoringDefaultPath(kind),selectedValue=kind==='ITEM'?($('#legacyItemCode')?.value||''):($('#legacyAuthoringItemCode')?.value||''),selectedItem=legacySelectedItem(selectedValue),selectedCode=selectedItem?.code||selectedValue;const base={kind,mode,path};if(mode==='CREATE'){if(kind==='ITEM')Object.assign(base,{fields:{name:selectedItem?.display_name||selectedItem?.name||'',code:selectedCode||'',weight:1,price:1}});else if(kind==='MONSTER')Object.assign(base,{payload:{fields:{name:'New Monster',model_file:'char/monster/new/new.ini',level:1,life:100,experience:1,attack_damage:[1,2],attack_speed:[1,1],attack_range:40,attack_rating:10,defence:5,absorption:0,sight:300},drops:[]}});else if(kind==='NPC')Object.assign(base,{payload:{fields:{name:'New NPC',model_file:'char/npc/new/new.ini',shop:true},dialogs:[],shops:{weapon:[],defence:[],etc:[]}}});else if(kind==='SPM')Object.assign(base,{payload:{actors:[{name:'Cuepy',weight:100}],max_actor:10,delay_seconds:10}});else if(kind==='SPP')Object.assign(base,{payload:{records:[{index:0,state:1,x:0,z:0}]}});else if(kind==='SPC')Object.assign(base,{payload:{records:[{index:0,name:'NEW_NPC',model_ini:'char/npc/new/new.ini',server_npc:'GameServer/NPC/NewNPC.npc',x:0,y:0,z:0}]}})}else{if(kind==='ITEM')Object.assign(base,{patch:{set:{price:1}}});else if(kind==='MONSTER')Object.assign(base,{patch:{set:{experience:1000}}});else if(kind==='NPC')Object.assign(base,{patch:{shops:{weapon:[],defence:[],etc:[]},dialogs:[]}});else if(kind==='SPM')Object.assign(base,{patch:{action:'ADD_ACTOR',name:'Cuepy',weight:100}});else if(kind==='SPP')Object.assign(base,{patch:{records:[{index:0,state:1,x:0,z:0}]}});else if(kind==='SPC')Object.assign(base,{patch:{action:'ADD',index:0,record:{name:'NEW_NPC',model_ini:'char/npc/new/new.ini',server_npc:'GameServer/NPC/NewNPC.npc',x:0,y:0,z:0}}})}return base}
function loadLegacyAuthoringTemplate(){const kind=$('#legacyAuthoringKind').value;if(!$('#legacyAuthoringPath').value.trim())$('#legacyAuthoringPath').value=legacyAuthoringDefaultPath(kind);S.legacyAuthoringManifest=null;$('#legacyAuthoringSpec').value=JSON.stringify(legacyAuthoringTemplate(),null,2);$('#legacyAuthoringResult').textContent=`Template ${kind}/${$('#legacyAuthoringMode').value} loaded. Adjust it and use Stage.`;syncLegacyAuthoringUi()}
async function inspectLegacyAuthoring(){const kind=$('#legacyAuthoringKind').value,path=$('#legacyAuthoringPath').value.trim();if(!path){toast('Enter the file path');return}S.legacyAuthoringManifest=null;syncLegacyAuthoringUi();try{const d=await api('/api/legacy-authoring/inspect?'+new URLSearchParams({kind,path}));$('#legacyAuthoringResult').textContent=JSON.stringify(d.result,null,2);$('#legacyAuthoringState').textContent=`${kind} · ${d.result.status}`;if(d.result.exists&&d.result.source_sha256){let spec;try{spec=JSON.parse($('#legacyAuthoringSpec').value||'{}')}catch{spec=legacyAuthoringTemplate()}spec.kind=kind;spec.mode='EDIT';spec.path=path;spec.expected_sha256=d.result.source_sha256;$('#legacyAuthoringMode').value='EDIT';$('#legacyAuthoringSpec').value=JSON.stringify(spec,null,2)}syncLegacyAuthoringUi();toast(d.result.exists?'File loaded for authoring':'New target; use CREATE')}catch(e){$('#legacyAuthoringResult').textContent=JSON.stringify({status:'ERROR',http_status:e.httpStatus||null,error:e.payload?.error||'INSPECT_FAILED',detail:e.message},null,2);toast(e.message)}}
async function stageLegacyAuthoring(){if(!S.boot.write_armed){$('#modal').classList.remove('hidden');toast('Arm workspace/build before creating the draft');return}let spec;try{spec=JSON.parse($('#legacyAuthoringSpec').value)}catch(e){toast('Invalid JSON: '+e.message);return}spec.kind=$('#legacyAuthoringKind').value;spec.mode=$('#legacyAuthoringMode').value;spec.path=$('#legacyAuthoringPath').value.trim();S.legacyAuthoringManifest=null;syncLegacyAuthoringUi();try{const d=await api('/api/legacy-authoring/stage',{method:'POST',body:{spec}});const r=d.result||{},m=r.manifest||{};S.legacyAuthoringManifest=m.manifest||m?.manifest?.manifest||r.manifest_path||null;if(!S.legacyAuthoringManifest)throw new Error('Stage completed without a publishable manifest');$('#legacyAuthoringResult').textContent=JSON.stringify(r,null,2);$('#legacyAuthoringState').textContent=`${spec.kind} · STAGED`;saveLegacyEditorState();syncLegacyAuthoringUi();toast('Authoring staged in pt_build; review the manifest before publishing')}catch(e){S.legacyAuthoringManifest=null;syncLegacyAuthoringUi();$('#legacyAuthoringResult').textContent=JSON.stringify({status:'ERROR',http_status:e.httpStatus||null,error:e.payload?.error||'STAGE_FAILED',detail:e.message},null,2);toast(e.message)}}
async function deployLegacyAuthoring(mode){try{if(mode==='status'){const d=await api('/api/asset-compiler/status');$('#legacyAuthoringResult').textContent=JSON.stringify(d.result,null,2);return}if(mode==='publish'&&!S.legacyAuthoringManifest){toast('Run Stage for this task before publishing');syncLegacyAuthoringUi();return}if(!(await armAssetDeploy()))return;const msg=mode==='publish'?'Publish the staged manifest for this task?\n\nHash preflight, backup, and post-write verification will run.':'Restore the latest authoring bundle?\n\nExternal drift blocks restore.';if(!confirm(msg)){S.boot.server_deploy_armed=false;return}const body={};if(mode==='publish')body.manifest=S.legacyAuthoringManifest;const d=await api('/api/asset-compiler/'+mode,{method:'POST',body});S.boot.server_deploy_armed=false;S.boot.server_deploy_armed_until=0;$('#legacyAuthoringResult').textContent=JSON.stringify(d.result,null,2);$('#legacyAuthoringState').textContent=mode==='publish'?'APPLIED_VERIFIED':'RESTORED_VERIFIED';if(mode==='publish'){S.legacyAuthoringManifest=null;saveLegacyEditorState()}toast(mode==='publish'?'Authoring published; validate in-game':'Authoring restored')}catch(e){S.boot.server_deploy_armed=false;S.boot.server_deploy_armed_until=0;$('#legacyAuthoringResult').textContent=JSON.stringify({status:'ERROR',http_status:e.httpStatus||null,error:e.payload?.error||'DEPLOY_FAILED',detail:e.message},null,2);toast(e.message)}finally{syncLegacyAuthoringUi()}}

let particleSearchTimer=null;
async function loadParticleAssets(){
  if(!$('#particleRows'))return;
  const q=$('#particleSearch')?.value.trim()||'';
  try{const d=await api('/api/particles?q='+encodeURIComponent(q));const rows=d.items||[];$('#particleCount').textContent=`${rows.length.toLocaleString()} .part`;$('#particleRows').innerHTML=rows.length?rows.map((r,i)=>`<tr data-particle-row="${i}"><td class="path" title="${esc(r.asset)}">${esc(r.asset)}</td><td>${fmtBytes(r.size)}</td></tr>`).join(''):'<tr><td colspan="2" class="empty">No .part file found.</td></tr>';$$('[data-particle-row]').forEach(tr=>tr.onclick=()=>selectParticle(rows[Number(tr.dataset.particleRow)].asset))}catch(e){$('#particleRows').innerHTML=`<tr><td colspan="2" class="empty">${esc(e.message)}</td></tr>`;$('#particleCount').textContent='Error'}
}
async function selectParticle(asset){
  try{const d=await api('/api/particles/inspect?asset='+encodeURIComponent(asset));S.particle=asset;renderParticleDetail(d.particle)}catch(e){toast(e.message)}
}
function renderParticleDetail(d){
  const fields=d.occurrences||[];const draft=d.draft||{};
  $('#particleDetail').innerHTML=`<div class="panel" style="margin:0"><div class="panel-title"><strong>${esc(d.asset)}</strong><span>${esc(d.authoring_status)} · ${esc(d.parse_status)}</span></div><div class="micro">SHA-256 ${esc(d.source_sha256)} · EOL ${esc(d.eol)} · client/server source write disabled</div><div class="server-explorer-table" style="max-height:46vh;overflow:auto;margin-top:10px"><table><thead><tr><th>Line</th><th>Selector</th><th>Type</th><th>Value / staging</th></tr></thead><tbody>${fields.map((o,i)=>{const sel=`${o.canonical_key}[${o.occurrence}]`;return `<tr><td>${Number(o.line||0)}</td><td><code>${esc(sel)}</code></td><td>${esc(o.value_kind||'—')}</td><td>${o.editable&&d.authoring_status==='EDITABLE_STAGING'?`<div style="display:flex;gap:6px"><input data-particle-value="${i}" value="${esc(o.value)}" style="min-width:220px;flex:1"><button class="btn small" data-particle-stage="${i}" data-selector="${esc(sel)}">Stage</button></div>`:esc(o.value)}</td></tr>`}).join('')}</tbody></table></div><div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:12px"><button id="particleVerify" class="btn">Verify draft</button><button id="particlePreviewPlan" class="btn">Generate preview plan</button><button id="particlePreviewRun" class="btn primary">Generate Blender preview</button></div><pre id="particleOutput" class="micro" style="white-space:pre-wrap;max-height:280px;overflow:auto">Draft: ${esc(JSON.stringify(draft,null,2))}</pre><img id="particlePreviewImage" hidden style="max-width:512px;width:100%;border-radius:6px"></div>`;
  $$('[data-particle-stage]').forEach(b=>b.onclick=()=>stageParticle(b.dataset.selector,$(`[data-particle-value="${b.dataset.particleStage}"]`).value));$('#particleVerify').onclick=particleVerify;$('#particlePreviewPlan').onclick=particlePreviewPlan;$('#particlePreviewRun').onclick=particlePreviewRun;
}
