function donorRecoveryAction(row){
  if(row.donor==='SUMMIT')return '';
  if(row.domain==='MAP_FIELD'&&row.side==='SERVER'&&String(row.relative_path||'').toLowerCase().endsWith('.spm')&&row.spawn_recovery_certified===true)return 'STAGE_SPAWN';
  if(['MONSTER','NPC','ITEM'].includes(row.domain)&&row.side==='SERVER')return row.domain;
  if(row.closed_recovery_bundle)return 'PHYSICAL_BUNDLE';
  return '';
}
function donorRecoveryActionLabel(action){return action==='STAGE_SPAWN'?'Stage SPM → canonical':action==='PHYSICAL_BUNDLE'?'Stage closed physical bundle':`Stage ${action} → canonical`}
function donorRecoveryVariantHtml(row){
  const action=donorRecoveryAction(row),payload=encodeURIComponent(JSON.stringify({action,donor_label:row.donor,relative_path:row.relative_path,side:row.side,root_path:row.closed_recovery_bundle?.root_path||''}));
  const badge=row.donor==='SUMMIT'?'TARGET':row.donor;
  const ident=row.canonical_field_identity||null;
  const identityHtml=ident&&ident.match_basis==='CANONICAL_STAGE_BASENAME_EXACT'?`<div class="micro">field ${esc(ident.legacy_field_code??'—')} · ${esc(ident.map_id||'—')} · stage <code>${esc(ident.canonical_stage||'—')}</code> · exact identity</div>`:row.domain==='MAP_FIELD'?`<div class="micro">no exact canonical stage identity</div>`:'';
  const names=(row.definition_name_evidence||[]).slice(0,4);const definitionHtml=names.length?`<div class="micro">definition name: ${names.map(esc).join(' · ')}${row.query_match?.match_basis?` · ${esc(row.query_match.match_basis)}`:''}</div>`:'';
  const recovery=action?`<button class="btn small donor-recovery-action" data-payload="${payload}">${esc(donorRecoveryActionLabel(action))}</button>`:'<span class="micro">read-only / no certified action</span>';
  return `<div class="donor-recovery-variant"><div><span class="badge">${esc(badge)}</span> <b>${esc(row.side)}</b> <code>${esc(row.relative_path)}</code>${identityHtml}${definitionHtml}</div><div>${recovery}</div></div>`;
}
function renderDonorRecovery(result){
  const tree=$('#donorRecoveryTree'),count=$('#donorRecoveryCount'),sel=$('#donorRecoveryDonor');if(!tree)return;
  const rawRows=[];for(const d of result?.donors||[])for(const group of Object.values(d.domains||{}))for(const row of group.nodes||[])rawRows.push(row);
  const entityDomains=result?.entity_tree||{};let entityCount=0;for(const g of Object.values(entityDomains))entityCount+=Number(g?.entity_count||0);
  count.textContent=`${entityCount.toLocaleString()} entities · ${rawRows.length.toLocaleString()} variants · ${result?.donors?.length||0} logical roots`;
  if(sel){const old=sel.value,labels=[...new Set((result?.donors||[]).filter(x=>!x.target).map(x=>x.label))];const current=[...sel.options].map(x=>x.value);for(const label of labels)if(!current.includes(label)){const o=document.createElement('option');o.value=label;o.textContent=label;sel.appendChild(o)}sel.value=old}
  const sections=[];
  for(const [domain,group] of Object.entries(entityDomains)){
    const entities=group?.entities||[];if(!entities.length)continue;
    const entityHtml=entities.map(entity=>`<details class="donor-recovery-entity"><summary><b>${esc(entity.label)}</b><span>${entity.variant_count||0} variant(s) · ${esc((entity.donor_labels||[]).join(', '))}${entity.has_target?' · target present':' · target missing'}</span></summary><div class="donor-recovery-variants">${(entity.variants||[]).map(donorRecoveryVariantHtml).join('')}</div></details>`).join('');
    sections.push(`<details class="donor-recovery-domain" open><summary><strong>${esc(domain)}</strong><span>${entities.length.toLocaleString()} entities</span></summary>${entityHtml}</details>`);
  }
  const diag=[];
  const qid=result?.map_field_query_identity;if(qid)diag.push(`Certified field identity: ${qid.legacy_field_code??'—'} · ${qid.map_id||'—'} · ${qid.canonical_stage||'—'}; donor SPM recovery requires this exact stage basename`);
  for(const d of result?.donors||[]){
    for(const [dom,sides] of Object.entries(d.scan_diagnostics||{})){
      for(const [side,x] of Object.entries(sides||{})){
        if(x?.state==='NO_DOMAIN_ROOT'){
          diag.push(`${d.label} ${side}: no ${dom} scan root under ${x.configured_root}`);
        }else if(x?.state==='NO_SIGNATURE_FILES_ANYWHERE'){
          diag.push(`${d.label} ${side}: recursive scan found 0 ${dom} signature files under ${x.configured_root}`);
        }else if(x?.state==='SIGNATURE_FILES_PRESENT_NO_QUERY_MATCH'){
          const f=x.fallback_recursive_scan||{};
          diag.push(`${d.label} ${side}: ${Number(f.signature_files_seen||0)} ${dom} signature file(s) exist, but none match this search`);
        }else if(x?.state==='READY_FALLBACK_RECURSIVE'){
          const f=x.fallback_recursive_scan||{};
          diag.push(`${d.label} ${side}: using recursive signature fallback (${Number(f.query_matches||0)} match(es), ${Number(f.signature_files_seen||0)} signature file(s) scanned)`);
        }
      }
    }
  }
  const diagHtml=diag.length?`<div class="donor-recovery-diagnostic"><b>Scan diagnostics</b><br>${diag.map(esc).join('<br>')}</div>`:'';
  tree.innerHTML=diagHtml+(sections.join('')||'<div class="empty">No matching donor entities.</div>');
}
async function loadDonorRecovery(){
  try{const domain=$('#donorRecoveryDomain')?.value||'',q=$('#donorRecoverySearch')?.value.trim()||'',donor=$('#donorRecoveryDonor')?.value||'';const d=await api('/api/donor-recovery/explorer?domain='+encodeURIComponent(domain)+'&q='+encodeURIComponent(q)+'&donor='+encodeURIComponent(donor)+'&limit=1500');renderDonorRecovery(d.result)}catch(e){if($('#donorRecoveryResult'))$('#donorRecoveryResult').textContent=e.message;toast(e.message)}
}
async function stageDonorRecovery(payload){
  try{const d=await api('/api/donor-recovery/stage',{method:'POST',body:payload});const r=d.result||d;$('#donorRecoveryResult').textContent=JSON.stringify(r,null,2);if(r?.manifest?.manifest&&$('#canonicalV211Manifest'))$('#canonicalV211Manifest').value=r.manifest.manifest;if(payload.action==='PHYSICAL_BUNDLE'&&r?.state==='STAGED_ONLY'){S.donorPhysicalStage={...payload};if($('#donorRecoveryPhysicalApply'))$('#donorRecoveryPhysicalApply').disabled=false;if($('#donorRecoveryPhysicalConfirm')){$('#donorRecoveryPhysicalConfirm').value='';$('#donorRecoveryPhysicalConfirm').placeholder='APPLY CLOSED DONOR BUNDLE'}}if(r.status==='BLOCKED_DEPENDENCIES'){S.donorBlockedSpawnPayload={action:'STAGE_SPAWN_DEPENDENCIES',donor_label:payload.donor_label,relative_path:payload.relative_path};const dep=r?.dependency_gate?.unresolved?.[0],cand=dep?.candidates?.[0];if($('#donorRecoveryStageUniqueDeps'))$('#donorRecoveryStageUniqueDeps').disabled=false;if($('#donorRecoveryDependencyHint'))$('#donorRecoveryDependencyHint').textContent='Auto-stage only unique LEGACY_NAME_BYTES_EXACT matches from the same donor; ambiguous definitions stay in review.';if($('#donorRecoveryDomain'))$('#donorRecoveryDomain').value='MONSTER';if($('#donorRecoverySearch'))$('#donorRecoverySearch').value=dep?.name||'';if(cand&&$('#donorRecoveryDonor'))$('#donorRecoveryDonor').value=cand.donor_label||'';loadDonorRecovery()}toast(r.status==='ALREADY_CANONICAL'?'Already canonical':r.status==='BLOCKED_DEPENDENCIES'?'Spawn blocked: Monster view focused on the first unresolved dependency; import/reconcile it, then retry':'Donor recovery staged; validate/apply through the explicit deployment phase')}catch(e){$('#donorRecoveryResult').textContent=e.message;toast(e.message)}
}
async function stageUniqueDonorSpawnDependencies(){
  if(!S.donorBlockedSpawnPayload){toast('Stage a blocked SPM first');return}const b=$('#donorRecoveryStageUniqueDeps');if(b)b.disabled=true;try{const d=await api('/api/donor-recovery/stage',{method:'POST',body:S.donorBlockedSpawnPayload});const r=d.result||d;$('#donorRecoveryResult').textContent=JSON.stringify(r,null,2);if(r?.manifest?.manifest&&$('#canonicalV211Manifest'))$('#canonicalV211Manifest').value=r.manifest.manifest;const left=Number(r?.dependency_batch?.remaining_review_count??((r.ambiguous||[]).length+(r.missing||[]).length));if($('#donorRecoveryDependencyHint'))$('#donorRecoveryDependencyHint').textContent=r.status==='STAGED'?`Dependency batch staged. Publish canonical source/packs/runtime, then retry the SPM. ${left} dependency decision(s) remain for review.`:`${r.status}: ${left} dependency decision(s) remain for review.`;toast(r.status==='STAGED'?'Unique exact monster dependencies staged as one canonical transaction':'Dependency batch requires review; see result')}catch(e){if($('#donorRecoveryResult'))$('#donorRecoveryResult').textContent=e.message;if(b)b.disabled=false;toast(e.message)}
}
async function applyDonorPhysical(){
  if(!S.donorPhysicalStage){toast('Stage one CLOSED physical bundle first');return}const confirm=$('#donorRecoveryPhysicalConfirm')?.value||'';try{const d=await api('/api/donor-recovery/apply-physical',{method:'POST',body:{...S.donorPhysicalStage,confirm}});const r=d.result||d;$('#donorRecoveryResult').textContent=JSON.stringify(r,null,2);if(r.transaction&&$('#donorRecoveryPhysicalTransaction')){$('#donorRecoveryPhysicalTransaction').value=r.transaction;$('#donorRecoveryPhysicalRestore').disabled=false;if($('#donorRecoveryPhysicalConfirm')){$('#donorRecoveryPhysicalConfirm').value='';$('#donorRecoveryPhysicalConfirm').placeholder='RESTORE CLOSED DONOR BUNDLE'}}S.donorPhysicalStage=null;$('#donorRecoveryPhysicalApply').disabled=true;toast('Physical donor bundle applied and verified')}catch(e){$('#donorRecoveryResult').textContent=e.message;toast(e.message)}
}
async function restoreDonorPhysical(){
  const transaction=$('#donorRecoveryPhysicalTransaction')?.value.trim()||'',confirm=$('#donorRecoveryPhysicalConfirm')?.value||'';if(!transaction){toast('Physical transaction manifest required');return}try{const d=await api('/api/donor-recovery/restore-physical',{method:'POST',body:{transaction,confirm}});const r=d.result||d;$('#donorRecoveryResult').textContent=JSON.stringify(r,null,2);$('#donorRecoveryPhysicalRestore').disabled=true;toast('Physical donor recovery restored')}catch(e){$('#donorRecoveryResult').textContent=e.message;toast(e.message)}
}
function bindDonorRecovery(){
  if($('#donorRecoveryRefresh'))$('#donorRecoveryRefresh').onclick=loadDonorRecovery;if($('#donorRecoveryDomain'))$('#donorRecoveryDomain').onchange=loadDonorRecovery;if($('#donorRecoveryDonor'))$('#donorRecoveryDonor').onchange=loadDonorRecovery;let t;if($('#donorRecoverySearch'))$('#donorRecoverySearch').oninput=()=>{clearTimeout(t);t=setTimeout(loadDonorRecovery,180)};if($('#donorRecoveryTree'))$('#donorRecoveryTree').onclick=e=>{const b=e.target.closest('.donor-recovery-action');if(!b)return;try{stageDonorRecovery(JSON.parse(decodeURIComponent(b.dataset.payload)))}catch(err){toast(err.message)}};if($('#donorRecoveryStageUniqueDeps'))$('#donorRecoveryStageUniqueDeps').onclick=stageUniqueDonorSpawnDependencies;if($('#donorRecoveryPhysicalApply'))$('#donorRecoveryPhysicalApply').onclick=applyDonorPhysical;if($('#donorRecoveryPhysicalRestore'))$('#donorRecoveryPhysicalRestore').onclick=restoreDonorPhysical;if($('#donorRecoveryPhysicalTransaction'))$('#donorRecoveryPhysicalTransaction').oninput=()=>{$('#donorRecoveryPhysicalRestore').disabled=!$('#donorRecoveryPhysicalTransaction').value.trim()};loadDonorRecovery()
}
setInterval(renderArm,15000);bind();bindCanonicalV211();bindDonorRecovery();switchLegacyTask(localStorage.getItem('ptAssetLegacyTask')||'item');boot().catch(e=>{console.error(e);toast('Failed to start UI: '+e.message)});
